const equal = (c, value) => JSON.stringify(c.expected) === JSON.stringify(value);
const pair = (c, value) => pairOK(c.args, value);
const C = (ru, en, args, expected) => ({ label: L(ru, en), args, ...(expected === undefined ? {} : { expected }) });
// Valid Towers of Hanoi answer: 2ⁿ − 1 legal moves that end with every disk on peg 2.
const hanoiOK = (c, moves) => {
  const n = c.args[0], p = [Array.from({ length: n }, (_, i) => n - i), [], []];
  if (!Array.isArray(moves) || moves.length !== 2 ** n - 1) return false;
  for (const m of moves) {
    if (!Array.isArray(m) || m.length !== 2 || !m.every(x => [0, 1, 2].includes(x)) || !p[m[0]].length) return false;
    if (p[m[1]].length && p[m[1]].at(-1) < p[m[0]].at(-1)) return false;
    p[m[1]].push(p[m[0]].pop());
  }
  return p[2].length === n;
};
